@RestController
@RequestMapping("/api/v1/orders")
public class StatelessOrderController {

    private final OrderProcessingService orderProcessingService;

    public StatelessOrderController(OrderProcessingService orderProcessingService) {
        this.orderProcessingService = orderProcessingService;
    }

    @PostMapping
    public ResponseEntity<OrderResponseDto> createOrder(
            @RequestHeader("X-User-Id") String userId, 
            @RequestBody OrderRequestDto requestDto) {

        // The service relies entirely on the passed header and payload, 
        // containing zero local state in the controller or JVM heap.
        OrderResponseDto response = orderProcessingService.process(userId, requestDto);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }
}
